function getSettingStatus(mode) {
    if (mode === undefined) mode = ""
    let keys = [], msgList = []
    let settings = getFromCacheObject("pixivSettings")
    if (mode === "FAST") {
        keys = Object.keys(settingsName).slice(0, 5)
    } else if (mode === "IPDirect") {
        keys = Object.keys(settingsName).slice(0, 2)
    } else {
