"packageName=com.lestory.jihua.an",
"lang-app=zh-Hans",
"lang=zh-hans",
"locale=CN"
]

function sign(list){
var sb='';
sb+="Fb0gqLMSf5Android";
list=list.sort();
i=0;
while(i<list.length){
if(i==0){
sb+=list[i]
}else{
    if(list[i].match(/lang-app=/)){  
      i2=i+1;
     i3=i2+1;
     if (list[i2] != null && list[i2].match(/lang=/)) {
                        sb+="&";
                        sb+=list[i2];

                        sb+="&";
                        sb+=list[i];

                        i = i3;
                    }
           }
                sb+="&";
                sb+=list[i];             
      }
i++
}
sb+="AEdDtho2CjiH901aVK7swFqclu6NmzJ4";
return String(java.md5Encode(sb)).toUpperCase()
}

s=sign(list);

json={"product":"1","ver":"2.1.3","sysVer":"10","locale":"CN","token":String(token),"lang-app":"zh-Hans","appId":"","osType":"2","time":time,"packageName":"com.lestory.jihua.an","lang":"zh-hans","sign":String(s)}

option={
"method": "POST",
"body": JSON.stringify(json)
}
url='http://api.lestory.cn/remain/report-reward,'+JSON.stringify(option);
i=10;

//循环1000次，15s一次
for(i=0;i<=1000;i++){ 
var start =(new Date()).getTime();
	// 阻塞15s
    while((new Date()).getTime() - start < 15000) {
        continue;
    }
java.log(JSON.parse(String(java.ajax(url))).data.reward_gold);
}}


